def normalize_currency(record):
    record = dict(record)
    if record.get("timezone") is None:
        record["timezone"] = "UTC"
    if record["currency"] == "EUR":
        record["amount"] = round(record["amount"] * 1.1, 2)
    # The target API accepts USD only.  Missing currency has already been
    # defaulted; this assignment also makes the outbound contract explicit.
    record["currency"] = "USD"
    return record

