from __future__ import annotations


def merge_profile(record, profile):
    merged = dict(record)
    profile = profile or {}
    # A JSON null is just as incomplete as an omitted request field.  Only
    # retain the request value when it is actually usable.
    if merged.get("timezone") is None:
        merged["timezone"] = profile.get("timezone")
    if merged.get("currency") is None:
        merged["currency"] = profile.get("currency")
    return merged

